// ---- Custom Icon Overrides (persisted in localStorage) ----
// Users can edit any icon's raw SVG markup (inner <path>/<circle>/... content)
// from Settings > Icons. Overrides are stored as { [iconKey]: "<svg inner markup>" }.
const CUSTOM_ICONS_KEY = "opay_custom_icons";

function getCustomIcons() {
  try {
    const raw = localStorage.getItem(CUSTOM_ICONS_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

function setCustomIcon(key, svgInner) {
  const all = getCustomIcons();
  if (svgInner && svgInner.trim()) {
    all[key] = svgInner.trim();
  } else {
    delete all[key];
  }
  localStorage.setItem(CUSTOM_ICONS_KEY, JSON.stringify(all));
}

function resetCustomIcon(key) {
  const all = getCustomIcons();
  delete all[key];
  localStorage.setItem(CUSTOM_ICONS_KEY, JSON.stringify(all));
}

function resetAllCustomIcons() {
  localStorage.removeItem(CUSTOM_ICONS_KEY);
}

// ---- Custom Icon IMAGES (picture uploads, persisted in localStorage) ----
// Takes priority over both custom SVG and the default built-in icon.
const CUSTOM_ICON_IMAGES_KEY = "opay_custom_icon_images";

function getCustomIconImages() {
  try {
    const raw = localStorage.getItem(CUSTOM_ICON_IMAGES_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

function setCustomIconImage(key, dataUrl) {
  const all = getCustomIconImages();
  if (dataUrl) {
    all[key] = dataUrl;
  } else {
    delete all[key];
  }
  localStorage.setItem(CUSTOM_ICON_IMAGES_KEY, JSON.stringify(all));
}

function resetCustomIconImage(key) {
  const all = getCustomIconImages();
  delete all[key];
  localStorage.setItem(CUSTOM_ICON_IMAGES_KEY, JSON.stringify(all));
}

function resetAllCustomIconImages() {
  localStorage.removeItem(CUSTOM_ICON_IMAGES_KEY);
}

window.getCustomIconImages = getCustomIconImages;
window.setCustomIconImage = setCustomIconImage;
window.resetCustomIconImage = resetCustomIconImage;
window.resetAllCustomIconImages = resetAllCustomIconImages;

window.getCustomIcons = getCustomIcons;
window.setCustomIcon = setCustomIcon;
window.resetCustomIcon = resetCustomIcon;
window.resetAllCustomIcons = resetAllCustomIcons;
window.ALL_ICON_KEYS = Object.keys(ICONS).sort();

function Icon(name, opts) {
  opts = opts || {};
  const size = opts.size || 20;
  const cls = opts.class || "";
  const strokeWidth = opts.strokeWidth || 2;
  const key = name.toLowerCase().replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();

  const customImages = getCustomIconImages();
  const custom = getCustomIcons();
  
  // Picture always takes priority over SVG
  if (customImages[key]) {
    return `<img src="${customImages[key]}" width="${size}" height="${size}" alt="${key}" class="lucide-icon icon-img ${cls}" style="object-fit:contain;display:inline-block;vertical-align:middle;border-radius:0;" />`;
  }
  
  // Then check for custom SVG
  const path = custom[key] || ICONS[key] || ICONS["circle"];
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round" class="lucide-icon ${cls}">${path}</svg>`;
}
window.Icon = Icon;
